<?php require __DIR__.'/config.php';$comments=db()->query('SELECT c.*,u.username,v.title FROM comments c JOIN users u ON u.id=c.user_id JOIN videos v ON v.id=c.video_id ORDER BY c.id DESC LIMIT 100')->fetchAll();require __DIR__.'/includes/header.php';?><div class="listing"><h2>Comments Room</h2><?php foreach($comments as $c):?><div class="comment"><a href="profile.php?id=<?=$c['user_id']?>"><?=h($c['username'])?></a> on <a href="watch.php?id=<?=$c['video_id']?>"><?=h($c['title'])?></a><p><?=nl2br(h($c['body']))?></p></div><?php endforeach;?><?php if(!$comments):?><p class="empty">No comments yet.</p><?php endif;?></div><?php require __DIR__.'/includes/footer.php';?>
